type MappedFsError = {
  code: "permission-denied" | "path-is-directory" | "fs-error";
  message: string;
  includeMeta: boolean;
};

function mapFsWriteError(err: any, path: string): MappedFsError {
  const phase: "mkdir" | "write" | undefined = err?.__phase;
  const fsCode = err?.code as string | undefined;

  if (fsCode === "EACCES" || fsCode === "EPERM") {
    return {
      code: "permission-denied",
      message: `Permission denied — cannot write: ${path}`,
      includeMeta: false,
    };
  }
  if (fsCode === "EISDIR") {
    return {
      code: "path-is-directory",
      message: `Path is a directory — cannot overwrite: ${path}`,
      includeMeta: false,
    };
  }
  if (fsCode === "ENOENT" && phase === "mkdir") {
    return {
      code: "fs-error",
      message: `Cannot create parent directories for ${path}: ${err?.message ?? String(err)}`,
      includeMeta: true,
    };
  }
  if (fsCode === "ENOSPC") {
    return {
      code: "fs-error",
      message: `No space left on device — cannot write: ${path}`,
      includeMeta: true,
    };
  }
  if (fsCode === "EROFS") {
    return {
      code: "fs-error",
      message: `Read-only filesystem — cannot write: ${path}`,
      includeMeta: true,
    };
  }
  return {
    code: "fs-error",
    message: `Error writing ${path}: ${err?.message ?? String(err)}`,
    includeMeta: true,
  };
}

export async function executeWrite(opts: {
  path: string;
  content: string;
  map?: boolean;
  cwd?: string;
}): Promise<WriteResult> {
  await ensureHashInit();

  const { path: filePath, content, map: requestMap, cwd } = opts;
  const warnings: string[] = [];
  const ptcWarnings: PtcWarning[] = [];
  const contextHygiene = buildContextHygieneMetadata({
    tool: "write",
    classification: "mutation",
    resources: [buildFileResource(filePath)],
  });

  if (hasBareCarriageReturn(content)) {
    const message = "File content contains bare CR (\\r) line endings; write refuses to emit anchors that read/edit would normalize differently.";
    warnings.push(message);
    ptcWarnings.push(buildPtcWarning("bare-cr", message));
    return {
      text: `Cannot write ${filePath}\n⚠️ ${message}`,
      warnings,
      ptcValue: {
        tool: "write",
        path: filePath,
        lines: [],
        warnings: ptcWarnings,
      },
      contextHygiene,
    };
  }
  const previousContent = readPreviousTextForDiff(filePath);
  const existedBeforeWrite = existsSync(filePath);

  // Atomic write (handles parent-dir creation, symlinks, hard links)
  try {
    await writeFileAtomically(filePath, content);
  } catch (err: any) {
    err.__phase = "write";
    throw err;
  }


  // Binary detection
  if (looksLikeBinary(Buffer.from(content, "utf-8"))) {
    warnings.push("File content appears to be binary.");
    ptcWarnings.push(buildPtcWarning("binary-content", "File content appears to be binary."));
    return {
      text: `Wrote ${filePath}\n⚠️ File content appears to be binary — hashlines not generated.`,
      warnings,
      writeState: existedBeforeWrite ? "overwritten" : "created",
      ptcValue: {
        tool: "write",
        path: filePath,
        lines: [],
        warnings: ptcWarnings,
      },
      contextHygiene,
    };
  }

  const displayPath = cwd ? relative(cwd, filePath) || filePath : filePath;
  const writeState: "created" | "overwritten" = existedBeforeWrite ? "overwritten" : "created";

  // Compute hashlines. Writes whose anchors would exceed the visible budget return a
  // compact summary and a bounded structured value instead (#273).
  const rawLines = splitDisplayLines(content);
  const ptcLines: PtcLine[] = [];
  let text = "";
  let compact = rawLines.length > MAX_LINES;
  if (!compact) {
    const displayLines: string[] = [];
    for (let i = 0; i < rawLines.length; i++) {
      const lineNum = i + 1;
      ptcLines.push(buildPtcLine(lineNum, rawLines[i]));
      displayLines.push(formatHashlineDisplay(lineNum, rawLines[i]));
    }
    text = displayLines.join("\n");
    compact = Buffer.byteLength(text, "utf8") > MAX_BYTES;
  }
  const contentBytes = Buffer.byteLength(content, "utf8");
  if (compact) {
    ptcLines.length = 0;
    text = formatCompactWriteSummary(displayPath, rawLines.length, contentBytes);
    const omittedMessage = `Anchors omitted: ${rawLines.length} lines exceed the write anchor budget (${MAX_LINES} lines / ${MAX_BYTES / 1024} KB); use read with offset/limit for anchors.`;
    warnings.push(omittedMessage);
    ptcWarnings.push(buildPtcWarning("anchors-omitted", omittedMessage));
  }

  // Optional structural map
  let mapAppended = false;
  if (requestMap) {
    try {
      const fileMap = await getOrGenerateMap(filePath);
      if (fileMap) {
        const mapText = formatFileMapWithBudget(fileMap);
        if (mapText) {
          text += "\n\n" + mapText;
          mapAppended = true;
        }
      }
    } catch {
      // Map generation failure is non-fatal
    }
  }

  if (compact) {
    return {
      text,
      warnings,
      writeState,
      ptcValue: {
        tool: "write",
        path: displayPath,
        lines: [],
        warnings: ptcWarnings,
        truncated: true,
        totalLines: rawLines.length,
        bytes: contentBytes,
        ...(requestMap !== undefined ? { map: { appended: mapAppended } } : {}),
      },
      contextHygiene,
    };
  }

  const normalizedPrevious = normalizeToLF(previousContent);
  const normalizedNext = normalizeToLF(content);
  const diffResult = generateWriteDiff(normalizedPrevious, normalizedNext);
  const diffData = buildDiffData({
    path: filePath,
    oldContent: normalizedPrevious,
    newContent: normalizedNext,
    diff: diffResult.diff,
  });

  return {
    text,
    warnings,
    writeState,
    diff: diffResult.diff,
    diffData,
    ptcValue: {
      tool: "write",
      path: displayPath,
      lines: ptcLines,
      warnings: ptcWarnings,
      diff: diffResult.diff,
      diffData,
      ...(requestMap !== undefined ? { map: { appended: mapAppended } } : {}),
    },
    contextHygiene,
  };
}

const WRITE_PARAMETERS = Type.Object({
  path: Type.String({ description: "New or existing file path; fully overwrites target" }),
  content: Type.String({ description: "Complete content; bare CR refused; binary gets no anchors" }),
  map: Type.Optional(Type.Boolean({ description: "Request a structural map after writing" })),
});

export function registerWriteTool(pi: ExtensionAPI, options: WriteToolOptions = {}) {
  const tool = {
    name: "write",
    label: "write",
    // As edit: a batch containing a write runs in call order.
    executionMode: "sequential" as const,
    description: WRITE_PROMPT_METADATA.description,
    promptSnippet: WRITE_PROMPT_METADATA.promptSnippet,
    promptGuidelines: WRITE_PROMPT_METADATA.promptGuidelines,
    parameters: WRITE_PARAMETERS,
    constrainedSampling: { type: "json_schema", strict: "prefer" } as const,
    async execute(_toolCallId: string, params: { path: string; content: string; map?: boolean }, _signal: AbortSignal | undefined, _onUpdate: any, ctx: any): Promise<any> {
      const normalized = normalizeToolParameters(WRITE_PARAMETERS, params);
      if (normalized.requiredNull) {
        return buildRequiredNullParameterError("write", normalized.requiredNull);
      }
      // Pi hosts convert numbers/booleans to strings before execute; direct callers do not.
      // Reject anything that is still not a string instead of failing deep inside the write.
      const rawWriteParams = normalized.value as Record<string, unknown>;
      for (const key of ["path", "content"] as const) {
        const value = rawWriteParams[key];
        if (typeof value !== "string") {
          const received = Array.isArray(value) ? "array" : typeof value;
          const message = `Invalid ${key}: expected string, received ${received}.`;
          return {
            content: [{ type: "text" as const, text: message }],
            isError: true,
            details: {
              ptcValue: { tool: "write" as const, ok: false, error: buildPtcError("invalid-type", message) },
            },
          };
        }
      }
      const normalizedParams = normalized.value as {
        path: string;
        content: string;
        map?: boolean;
      };
      const cwd = ctx?.cwd ?? process.cwd();
      const absolutePath = resolveToCwd(normalizedParams.path, cwd);
      // Best-effort: resolve the symlink/hard-link target so aliases serialize on
      // one queue key. If resolution itself fails (e.g. ELOOP), fall back to the
      // literal path; writeFileAtomically re-resolves and surfaces the error
      // through the structured fs-error envelope in the catch below.
      let queueKey = absolutePath;
      try {
        queueKey = await resolveMutationTargetPath(absolutePath);
      } catch {
        // keep queueKey = absolutePath
      }
      return withFileMutationQueue(queueKey, async () => {
        let result: WriteResult;
        try {
          result = await executeWrite({
            path: absolutePath,
            content: normalizedParams.content,
            map: normalizedParams.map,
            cwd,
          });
        } catch (err: any) {
          const mapped = mapFsWriteError(err, absolutePath);
          return {
            content: [{ type: "text" as const, text: mapped.message }],
            isError: true,

